    glossary=[("Bias", "Systematic unfairness in how a system treats groups."), ("Training data", "The examples a system learns from. Gaps become bias."), ("Copyright", "The legal right of a creator to control copies."), ("Creative Commons", "Licenses that let creators share work with set permissions."), ("Open source", "Code anyone may read, use, and change under its license."), ("PII", "Personally identifiable information: data that can identify a person."), ("Metadata", "Data about data, like when and where a photo was taken."), ("Cookie", "A small file a site stores to remember you."), ("Authentication", "Proving you are who you claim to be."), ("Multifactor authentication", "Using two or more kinds of proof."), ("Phishing", "A fake message that tricks you into giving up information."), ("Malware", "Software designed to harm or spy."), ("Encryption", "Scrambling data so only the key holder can read it."), ("DDoS", "Overwhelming a site with traffic from many devices.")],
